<script setup lang="ts">const shop=useShop();const q=ref('');const lowOnly=ref(false);const list=computed(()=>shop.products.filter(p=>(!q.value||p.name.toLowerCase().includes(q.value.toLowerCase()))&&(!lowOnly.value||p.stock<5)));function change(id:string,delta:number){const p=shop.products.find(p=>p.id===id);if(p){p.stock=Math.max(0,p.stock+delta);shop.saveProducts()}} </script><template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-10"><p class="text-xs font-bold uppercase tracking-[.2em] text-brand">Admin demo</p><h1 class="mt-2 text-4xl font-semibold tracking-tight">Inventory<span class="text-brand">.</span></h1><div class="mt-6 flex flex-wrap gap-3"><input v-model="q" class="min-w-0 flex-1 rounded-full border border-gray-200 px-4 py-3 text-sm" placeholder="Search inventory"><label class="flex items-center gap-2 rounded-full border border-gray-200 px-4 py-3 text-xs"><input v-model="lowOnly" type="checkbox" class="accent-brand">Low stock only (&lt; 5)</label></div><div class="mt-6 overflow-x-auto rounded-2xl border border-gray-100"><table class="w-full min-w-[620px] text-left text-sm"><thead class="bg-mist text-xs uppercase tracking-wider text-gray-500"><tr><th class="p-4">Product</th><th class="p-4">Stock</th><th class="p-4">Adjust</th></tr></thead><tbody><tr v-for="p in list" :key="p.id" class="border-t border-gray-100"><td class="p-4 font-semibold">{{ p.name }}</td><td class="p-4" :class="p.stock<5?'font-bold text-red-600':''">{{ p.stock }} units</td><td class="p-4"><div class="flex items-center gap-2"><button class="h-8 w-8 rounded-full border" @click="change(p.id,-1)">−</button><button class="h-8 w-8 rounded-full border" @click="change(p.id,1)">+</button><button class="rounded-full bg-ink px-3 py-2 text-[10px] font-bold uppercase tracking-wider text-white" @click="change(p.id,5)">+5</button></div></td></tr></tbody></table></div><NuxtLink to="/admin" class="mt-6 inline-block text-xs font-semibold text-gray-500">← Back to dashboard</NuxtLink></div></template>
